export function chineseIdToolCopy(mode: "validator" | "generator"): Record<Locale, ToolCopy> {
  const copy = {} as Record<Locale, ToolCopy>;
  for (const locale of LOCALES) {
    const m = metadata[locale];
    const l = CHINESE_ID_MESSAGES[locale];
    copy[locale] = {
      name: m[mode], tagline: mode === "validator" ? m.validationTagline : m.generationTagline,
      intro: [mode === "validator" ? l.inputHint + " " + l.converted : l.sampleNote, l.limitNote, l.localNote],
      steps: mode === "validator" ? m.validationSteps : m.generationSteps,
      faqs: [{ q: m.limitsQuestion, a: l.limitNote + (mode === "generator" ? " " + l.sampleNote : "") }, { q: m.privacyQuestion, a: l.localNote + " " + l.maskedNote }],
    };
  }
  return copy;
}
